"""Preserve three delivered FastEOS profiles and expose the earlier FEOS handoff."""
from pathlib import Path
import hashlib,json,math,sys
import numpy as np
P=Path(__file__).resolve().parent;ROOT=P.parent.parent;RAW=Path('/home/tkwa/src/protium-fusion/output/assembly-audit');OUT=Path('/home/tkwa/src/protium-fusion/output/assembly-burn')
sys.path[:0]=[str(ROOT),str(ROOT/'component-design/assembly-audit')]
from fast_eos import FastEOS
from feos_contact import FEOS
