def energy(eos,r,T,m,v,y):
 ye=float(pm.ZZ@y);yi=float(sum(y));rho=m/(4*np.pi/3*np.diff(r**3));st=eos.state(rho/1000,T,ye,yi);nm=np.r_[.5*(m[:-1]+m[1:]),.5*m[-1]]
 return {'rho':rho,'p':st.p*.1,'specific_u':st.e*1e-4,'U_J':float(m@(st.e*1e-4)),'K_J':float(.5*nm@(v[1:]**2))}
def main():
 OUT.mkdir(parents=True,exist_ok=True);eos=FastEOS();trace=RAW/'B1-backward-feos128.npz';back=np.load(trace);j=int(np.argmin(abs(back['time_s']-30e-6)));assert abs(back['time_s'][j]-30e-6)<1e-14
 record=json.loads((RAW/'B1-forward-k0.json').read_text());Y=record['assembly_forward_inputs']['initial_Y'];y=np.array([Y.get(s,0) for s in pm.SPECIES]);assert math.isclose(y[pm.SPECIES.index('p')]/y[pm.SPECIES.index('n15')],2.)
 m=back['mass_kg'];r=back['radius_m'][j];v=-back['reverse_velocity_m_s'][j];T=back['temperature_K'][j];fast=energy(eos,r,T,m,v,y);feos=FEOS(cache=OUT/'feos');states=[feos.state('B1',den,temp) for den,temp in zip(fast['rho'],T)];fp=np.array([s['p_Pa'] for s in states]);fu=np.array([s['u_J_kg'] for s in states]);assert all(s['status']==0 for s in states)
 backmeta=json.loads(trace.with_suffix('.json').read_text());fw=float(back['internal_J'][j]);fk=float(back['kinetic_J'][j]);ff=float(m@fu)
 basepath=ROOT/'component-design/source-family-carbon-median128/records/B1-H2-source128-carbon-median.json';base=json.loads(basepath.read_text())
 bridge={'scope':'FEOS to FastEOS handoff is at the common preparation precursor,30us before delivered endpoints. All three forward preparation trajectories and the hot burns use FastEOS. No further EOS conversion is applied at burn start.','backward_trace':str(trace),'backward_trace_sha256':sha(trace),'precursor_index':j,'original_source_FastEOS_prepared_J':base['initial_energy_J'],'original_target_FEOS_prepared_J':backmeta['energy']['initial_total_J'],'precursor_FEOS_pressure_work_U_J':fw,'precursor_FEOS_direct_U_J':ff,'precursor_K_J':fk,'precursor_FEOS_pressure_work_total_J':fw+fk,'precursor_FEOS_direct_total_J':ff+fk,'precursor_FastEOS_U_J':fast['U_J'],'precursor_FastEOS_K_J':fast['K_J'],'precursor_FastEOS_prepared_J':fast['U_J']+fast['K_J'],'FastEOS_minus_FEOS_pressure_work_J':fast['U_J']-fw,'FastEOS_minus_FEOS_direct_J':fast['U_J']-ff,'pressure_FastEOS_over_FEOS_mass_weighted_ratio':float(m@fast['p']/(m@fp)),'pressure_FastEOS_over_FEOS_minmax':[float(min(fast['p']/fp)),float(max(fast['p']/fp))],'pressure_FastEOS_minus_FEOS_relative_mass_L1':float(m@abs(fast['p']-fp)/(m@fp)),'FEOS_library_sha256':sha(feos.library),'FEOS_helper_sha256':sha(ROOT/'component-design/assembly-audit/feos_contact.py'),'FastEOS_code_sha256':sha(ROOT/'fast_eos.py'),'FastEOS_table_sha256':sha(ROOT/'electron-eos.npz'),'rho_kg_m3':fast['rho'].tolist(),'T_K':T.tolist(),'mass_kg':m.tolist(),'FEOS_p_Pa':fp.tolist(),'FastEOS_p_Pa':fast['p'].tolist(),'FEOS_specific_u_J_kg':fu.tolist(),'FastEOS_specific_u_J_kg':fast['specific_u'].tolist(),'energy_scope':'Raw EOS energies include their own reference conventions. Their difference is an exposed model handoff discrepancy, not established physical heater work or free energy. No temperature/velocity/energy renormalization is performed.'}
 rows={}
 for label in ['k0','k0p001','k0p01']:
  src=RAW/('B1-forward-'+label+'.json');d=json.loads(src.read_text());assert d['success'] and d['termination_reason']=='final_time' and not d['nuclear_enabled'];assert d['assembly_forward_inputs']['initial_Y']==Y
  p=d['profile'];r=np.r_[0.,p['outer_radius_m']];v=np.r_[0.,p['velocity_m_s']];T=np.array(p['T_K']);assert len(T)==128;mass=d['mass_kg']*np.array(p['mass_fraction_of_total']);e=energy(eos,r,T,mass,v,y);start=e['U_J']+e['K_J'];prep=d['initial_energy_J'];escaped=d['radiation_escaped_J'];assert max(abs(e['rho']/np.array(p['rho_kg_m3'])-1))<1e-12;assert abs(start/(d['final_internal_J']+d['final_kinetic_J'])-1)<1e-12;assert abs((start+escaped)/prep-1)<1e-9;assert abs(prep/(fast['U_J']+fast['K_J'])-1)<1e-12
  profile={k:p[k] for k in ['outer_radius_m','velocity_m_s','T_K','mass_fraction_of_total']};profile['description']='Exact delivered FastEOS endpoint after30us whole-fluid preparation; no energy or velocity renormalization. Preparation '+label+'.'
  inputs={'stage':'B1','case':'B1-delivered-'+label,'initial_Y':Y,'hydrogen_per_catalyst':2.,'duration_s':base['elapsed_s'],'physical_duration_s':base['elapsed_s'],'zones':128,'T0_K':base['T0_K'],'rho0_kg_m3':base['rho0_kg_m3'],'R0_m':base['R0_m'],'rtol':base['rtol'],'atol':base['atol'],'opacity_m2_kg':.001,'radiation':True,'art_linear':.5,'art_quad':2.,'viscosity_mode':'compression_cap','preparation_record':str(src),'preparation_record_sha256':sha(src),'preparation_trace_sha256':sha(src.with_suffix('.npz')),'preparation_profile_sha256':sha(src.with_suffix('.initial.json')),'preparation_initial_energy_J':prep,'preparation_escaped_radiation_J':escaped,'burn_start_energy_J':start,'burn_start_internal_J':e['U_J'],'burn_start_kinetic_J':e['K_J'],'burn_start_rho_reconstruction_max_relative':float(max(abs(e['rho']/np.array(p['rho_kg_m3'])-1))),'preparation_plus_escape_energy_relative_error':(start+escaped)/prep-1,'hot_settings_reference':str(basepath),'hot_settings_reference_sha256':sha(basepath),'scope':'All hot settings and composition held fixed; only the delivered preparation endpoint differs. Preescaped radiation remains a separate outer energy account. The30us precursor is an auxiliary spherical-fluid boundary construction, not a qualified3D cold-launch trajectory.'}
  write(P/'inputs'/('B1-delivered-'+label+'.initial.json'),profile);write(P/'inputs'/('B1-delivered-'+label+'.inputs.json'),inputs);rows[label]=inputs
 write(P/'bridge.json',bridge);write(P/'prepared-cases.json',{'code_sha256':sha(__file__),'cases':rows});print(json.dumps({'bridge':{k:v for k,v in bridge.items() if not isinstance(v,list)},'cases':{k:{q:v[q] for q in ['preparation_initial_energy_J','preparation_escaped_radiation_J','burn_start_energy_J']} for k,v in rows.items()}},indent=2))
if __name__=='__main__':main()
